/** WKS-SA0-TRN-DEST PIC 9(09): las condiciones 88 que P053 reconoce. */
public enum TipoConsulta {
    CON_INST(15102100), CON_HIST(15102110),          // definidas, sin rama en 300000-PROCESA-TRANSACC
    CON_011(15153011),  CON_001(15153001),           // idem
    CON_012(15153012),                               // 310012-TRANS-12
    CON_018(15153018),  CON_119(15153119),           // 310018-TRANS-18
    CON_112(15153112),                               // 310112-TRANS-112
    CON_118(15153118);                               // 310118-TRANS-118

    private final int trnDest;
    TipoConsulta(int trnDest) { this.trnDest = trnDest; }

    public static Optional<TipoConsulta> de(int trnDest) {
        return Arrays.stream(values()).filter(t -> t.trnDest == trnDest).findFirst();
    }
}

/** PMC-DATOS-CTA: entrada y salida de PLATINO IN S151L011 (variante normal). */
public record ConsultaMovimientos(
        int funcion,                 // PMC-FUN 9(02)
        LocalDate fecha,             // PMC-FECHA 9(08) COMP, AAAAMMDD
        int sistema,                 // PMC-SIST 9(04)
        int producto, int instrumento, int medioAcceso,
        int sucursalPromotora,       // PMC-SUC-PROM 9(04)
        String cuenta,               // PMC-CTA 9(16): String para conservar ceros
        long autApl,                 // PMC-AUTAPL 9(10): llave de paginación
        int numMovs,                 // PMC-NUM-MOVS 9(02)
        List<Movimiento> movimientos) {  // OCCURS 20

    public static final int MAX_MOVS = 20;

    public record Movimiento(int cveMde, int sucOpe, int caja, long autoriz, int cve,
                             String referencia,          // 9(16)
                             BigDecimal saldo,           // 9(14)V99 COMP: escala 2, sin signo
                             LocalTime hora, int status, String leyenda,
                             int moneda, int bancoOrigen, int bancoDestino) {}
}

